create table documents (
    id           number(*, 0)
        generated by default on null as identity
    not null enable,
    file_name    varchar2(900 byte),
    file_size    number(*, 0),
    file_type    varchar2(100 byte),
    file_content blob
);

alter table documents add primary key ( id )
    using index enable;


